package org.kanger.storage.dumb2;
import java.util.*;import java.nio.file.*;import org.kanger.*;import org.kanger.command.*;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
public final class ContextRankBudgetPublicationRunner {
 static int checks;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static String rule(int n){StringBuilder b=new StringBuilder("!");for(int i=0;i<n;i++)b.append("$v").append(i).append(' ');b.append("wide(");for(int i=0;i<n;i++){if(i>0)b.append(',');b.append('v').append(i);}return b.append(");").toString();}
 static Map<String,Integer> bounds(int rank,int witnesses){Map<String,Integer> b=new LinkedHashMap<>();b.put("rank",rank);b.put("witnesses",witnesses);b.put("origins",0);return b;}
 static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("rank-budget-publication-");System.setProperty("user.home",d.toString());String original=rule(65);
  String command="ctx candidate model write \""+original+"\" rank=65 witnesses=65 origins=0";CommandParser parser=new CommandParser();CommandInvocation parsed=parser.parse(command);require(parsed.getArgument("request").equals(parser.parse(new CommandFormatter().format(parsed)).getArgument("request")),"rank/imported budget options survive canonical request roundtrip");for(String suffix:new String[]{"rank=0","origins=-1","rank=65 rank=66"}){boolean bad=false;try{parser.parse("ctx candidate model write \"!p(1);\" "+suffix);}catch(Exception expected){bad=true;}require(bad,"invalid/duplicate rank policy rejected before authoring");}
  try(Fixture f=new Fixture(d,"Wide")){String[] out=ContextAutomaticModelMatrix.console(f.mind,command+"\n");require(out[0].contains("MODEL WRITE: PUBLISHED")&&out[1].trim().isEmpty(),"actual Console rank65 publication with explicit budgets");}
  try(Fixture f=new Fixture(d,"Wide")){require(primary(f).equals(Collections.singleton(original)),"all65 original argument identities durable after cold reopen");StringBuilder q=new StringBuilder("?wide(");for(int i=0;i<65;i++){if(i>0)q.append(',');q.append('1');}q.append(");");require(f.mind.query(q.toString(),null,false)==null,"one chosen model value for65 Origins is not a concrete ground fact");}
  try(Fixture f=new Fixture(d,"DefaultFive")){require(f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(rule(5),Collections.emptyMap())).status==ContextSignedModelPublication.Status.PUBLISHED,"default rank8 admits five genuine binders after removal of unrelated capture4 cap");}
  try(Fixture f=new Fixture(d,"Limited")){long revision=f.db.getRevision();for(Map<String,Integer> b:Arrays.asList(bounds(64,65),bounds(65,64))){ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(original,b));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE&&primary(f).isEmpty()&&revision==f.db.getRevision(),"native/model rank refusals atomic, no false conflict or partial original");}}
  StringBuilder not=new StringBuilder("!");for(int i=0;i<17;i++)not.append("@v").append(i).append(' ');not.append("~wide(");for(int i=0;i<17;i++){if(i>0)not.append(',');not.append('v').append(i);}not.append(");");ContextNativeCandidateLeaseMatrix.create(d,"Negative",not.toString());
  try(Fixture f=new Fixture(d,"Refuted")){f.db.connectContext("Negative");long revision=f.db.getRevision();Map<String,Integer> b=bounds(17,0);b.put("cells",0);ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(rule(17),b));require(no.status==ContextSignedModelPublication.Status.REFUTED&&no.evidence!=null,"rank17 native proof precedes zero model witnesses/cells/imported budget");no.evidence.check(64000000,64);require(primary(f).isEmpty()&&revision==f.db.getRevision(),"rank17 sourced refusal leaves CURRENT unchanged");}
  System.out.println("CONTEXT_RANK_BUDGET_PUBLICATION_PASS checks="+checks);System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
